 * 
 * Given a list of stones' positions (in units) in sorted ascending order, determine if the frog is 
 * able to cross the river by landing on the last stone. Initially, the frog is on the first stone and 
 * assume the first jump must be 1 unit.
 * 
 * If the frog's last jump was k units, then its next jump must be either k - 1, k, or k + 1 units. 
 * Note that the frog can only jump in the forward direction.
 * 
 * Note:
 * 
 * The number of stones is &ge; 2 and is 
 * Each stone's position will be a non-negative integer 31.
 * The first stone's position is always 0.
 * 
 * Example 1:
 * 
 * [0,1,3,5,6,8,12,17]
 * 
 * There are a total of 8 stones.
 * The first stone at the 0th unit, second stone at the 1st unit,
 * third stone at the 3rd unit, and so on...
 * The last stone at the 17th unit.
 * 
 * Return true. The frog can jump to the last stone by jumping 
 * 1 unit to the 2nd stone, then 2 units to the 3rd stone, then 
 * 2 units to the 4th stone, then 3 units to the 6th stone, 
 * 4 units to the 7th stone, and 5 units to the 8th stone.
 * 
 * Example 2:
 * 
 * [0,1,2,3,4,8,9,11]
 * 
 * Return false. There is no way to jump to the last stone as 
 * the gap between the 5th and 6th stone is too large.
 * 
 ******************************************************************************************************/

class Solution {
    public boolean canCross(int[] stones) {
        cache = new HashMap<String, Boolean>();
        return helper(stones, 0, 0);
    }

    Map<String, Boolean> cache;

    boolean helper(int[] stones, int index, int units) {
        if (index == stones.length - 1) {
            return true;
        }

        var key = index + ":" + units;
        if (cache.containsKey(key)) {
            return cache.get(key);
        }

        var result = false;
        Outter:
        for (var i = index + 1; i < stones.length; i++) {
            if (stones[index] + units + 1 < stones[i]) {
                break;
            }

            for (var j = units - 1; j <= units + 1; j++) {
                if (j >= 0 && stones[index] + j == stones[i] && helper(stones, i, j)) {
                    result = true;
                    break Outter;
                }
            }
        }

        cache.put(key, result);
        return result;
    }
}

class Solution {
public:
    unordered_map<int, int> mark;
    int dp[2001][2001];

    int solve(vector<int>& stones, int n, int index, int prevJump) {
        // If reached the last stone, return 1.
        if (index == n - 1) {
            return 1;
        }

        // If this subproblem has been already calculated, return it.
        if (dp[index][prevJump] != -1) {
            return dp[index][prevJump];  
        }

        int ans = false;
        // Iterate over the three possibilities {k - 1, k, k + 1}.
        for (int nextJump = prevJump - 1; nextJump <= prevJump + 1; nextJump++) {
            if (nextJump > 0 && mark.find(stones[index] + nextJump) != mark.end()) {
                ans = ans || solve(stones, n, mark[stones[index] + nextJump], nextJump);
            }
        }

        // Store the result to fetch later.
        return dp[index][prevJump] = ans;
    }

    bool canCross(vector<int>& stones) {
        // Mark stones in the map to identify if such stone exists or not.
        for (int i = 0 ; i < stones.size(); i++) {
            mark.insert({stones[i], i});
        }

        // Mark all states as -1 to denote they're not calculated.
        memset(dp, -1, sizeof(dp));
        return solve(stones, stones.size(), 0, 0);
    }
};

